import copy,hashlib,json,time,traceback
from pathlib import Path
import numpy as np
from rmuc2027_research.rl.warp_kinematic.arena import ArenaMotion
from rmuc2027_research.rl.warp_kinematic.batching import BatchClient,WorldBatch
from test_locomotion_dynamics import command,feedback
p=Path(__file__).resolve().parent
files=[Path('research/rmuc2027_research/rl/warp_kinematic')/n for n in ('arena.py','batching.py','dynamics.py')]
source={str(q):hashlib.sha256(q.read_bytes()).hexdigest() for q in files}
start=time.time();out={'kind':'bounded_gpu_state_chain_probe','started_unix':start,'max_wall_seconds':60,'training_updates':0,'native_matches':0,'worlds':2,'requested_ticks':14,'completed_ticks':0,'world_frame_integrations':0,'source_sha256':source,'passed':False}
commands=[command(1.,2772),command(2.,2772)];commands[0]['robots'][0]['jump']=.2;commands[1]['robots'][0]['jump']=.8
clients=[BatchClient(None,'cuda:0') for _ in commands];solos=[ArenaMotion('cuda:0') for _ in commands];batches={}
for c,v in zip(clients,commands):c.ids=tuple(r['id'] for r in v['robots'])
try:
 for tick in range(14):
  if time.time()-start>52:raise TimeoutError('Probe internal wall limit')
  order=[0,1] if tick%2==0 else [1,0]
  if tick==1:
   for v in commands:v['robots'][0]['jump']=0.
  if tick==3:commands[0]['robots'][0].update(pos=[4.,4.,0.],velocity=[0.,0.,0.],grounded=True)
  if tick==4:commands[0]['robots'][0]['jump']=.6
  key=tuple(order)
  if key not in batches:batches[key]=WorldBatch('cuda:0')
  frames=batches[key].step_many([(clients[i],commands[i]) for i in order]);out['world_frame_integrations']+=2
  for i,actual in zip(order,frames):
   expected=solos[i].step(copy.deepcopy(commands[i]));out['world_frame_integrations']+=1
   for field in ('positions','velocities','rotations','angular_velocities','legs','grounded'):
    np.testing.assert_array_equal(actual[field],expected[field],err_msg=str((tick,i,field)))
   feedback(commands[i],actual)
  if tick==3:
   assert clients[0].state[0,18]==0.,'reset retained previous jump strength'
   assert abs(clients[1].state[0,18]-.8)<1e-6,'another world changed strength during reset'
  out['completed_ticks']=tick+1
 out.update(passed=True,final_strengths=[float(c.state[0,18]) for c in clients],external_protocol_versions=[f['version'] for f in frames])
except BaseException as e:
 out.update(error=type(e).__name__+': '+str(e),traceback=traceback.format_exc())
finally:
 for e in list(batches.values())+solos:e.close()
 out.update(wall_seconds=time.time()-start,source_unchanged=source=={str(q):hashlib.sha256(q.read_bytes()).hexdigest() for q in files})
 (p/'gpu-jump-state-result.json').write_text(json.dumps(out,indent=2,allow_nan=False)+'\n');print(json.dumps(out))
raise SystemExit(0 if out['passed'] else 1)

