const fs=require('node:fs'),path=require('node:path');
const {chromium}=require('/home/lx/kenreri/todo-list/.repo-tools/workspace-qa/node_modules/playwright-core');
const out=__dirname,tag=process.argv[2]||'before',url='http://127.0.0.1:8776';
const report={started:new Date().toISOString(),new_physics_matches:0,api_stubbed:false,errors:[],console_errors:[],requests_failed:[],mutations:[],cases:[]};
let browser;
const assert=(x,m)=>{if(!x)throw Error(m);};
const ready=()=>{const c=document.querySelector('#viewport canvas');return Boolean(c&&c.width&&c.height&&!document.querySelector('.scene-loading,.scene-recovery'));};
(async()=>{
 const timer=setTimeout(()=>{void browser?.close();},210000);
 try{
  browser=await chromium.launch({executablePath:'/usr/bin/google-chrome',headless:true,args:['--no-sandbox','--disable-dev-shm-usage','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']});
  const page=await browser.newPage({viewport:{width:1360,height:960}});page.setDefaultTimeout(30000);
  await page.addInitScript(()=>{window.probeRaf={last:0,intervals:[]};const sample=now=>{const p=window.probeRaf;if(p.last)p.intervals.push(now-p.last);p.last=now;p.intervals=p.intervals.slice(-20);requestAnimationFrame(sample);};requestAnimationFrame(sample);});
  page.on('pageerror',e=>report.errors.push(String(e)));
  page.on('console',m=>{if(m.type()==='error')report.console_errors.push(m.text());});
  page.on('requestfailed',r=>report.requests_failed.push({url:r.url(),error:r.failure()?.errorText}));
  page.on('request',r=>{if(r.method()!=='GET')report.mutations.push({method:r.method(),url:r.url()});});
  const snapshot=()=>page.evaluate(()=>({at:performance.now(),diagnostics:window.arenaDiagnostics?.(),timeline:document.querySelector('#timeline')?.value,max:document.querySelector('#timeline')?.max,canvas:!!document.querySelector('#viewport canvas'),loading:!!document.querySelector('.scene-loading'),recovery:!!document.querySelector('.scene-recovery'),memory:performance.memory?.usedJSHeapSize,raf:window.probeRaf,visibility:document.visibilityState,backend:document.querySelector('.architecture-tags')?.textContent,transport:document.querySelector('.transport')?.textContent,match_state:document.querySelector('#match-state')?.textContent,alerts:[...document.querySelectorAll('[role="alert"]')].map(x=>x.textContent)}));
  await page.goto(url,{waitUntil:'domcontentloaded'});
  for(const [run,label] of [
   ['sentry-v6-20261111-0333','main-rapier-blue-candidate'],
   ['sentry-v6-extension-20261111-0457-r03','worker-0-episode-00009'],
   ['sentry-v6-20261111-0333','main-rapier-blue-baseline'],
  ]){
   const row={run,label,started:Date.now(),samples:[]};report.cases.push(row);
   await page.getByRole('button',{name:'研究',exact:true}).click();
   await page.getByLabel('研究运行').selectOption(run);
   const selected=page.getByRole('row').filter({has:page.getByText(label,{exact:true})});
   await selected.getByRole('button',{name:'观看',exact:true}).click();
   await page.waitForFunction(()=>window.arenaDiagnostics?.().page==='arena'&&window.arenaDiagnostics?.().mode==='replay');
   row.loaded_ms=Date.now()-row.started;row.samples.push(await snapshot());
   await page.waitForFunction(ready,undefined,{timeout:60000});row.assets_ready_ms=Date.now()-row.started;
   const timeline=page.locator('#timeline');await timeline.focus();await timeline.press('Home');await timeline.press('ArrowRight');
   await page.waitForTimeout(250);row.paused=await snapshot();
   if(tag!=='before')assert(row.paused.diagnostics.tick===1&&row.paused.diagnostics.replayPosition===1&&row.paused.diagnostics.replayPlaying===false,'Seek did not immediately align UI position and renderer feed');
   await page.waitForTimeout(1500);row.paused_later=await snapshot();
   assert(row.paused_later.diagnostics.tick===row.paused.diagnostics.tick,'Paused timeline advanced');
   if(tag!=='before')await page.waitForFunction(()=>window.arenaDiagnostics?.().renderedTick===1);
   await page.locator('#pause').click();
   await page.waitForFunction(tick=>window.arenaDiagnostics?.().tick>tick,row.paused_later.diagnostics.tick);
   const start=await snapshot();await page.waitForTimeout(3000);const finish=await snapshot();
   row.playback={start,finish,observed_sim_s:(finish.diagnostics.tick-start.diagnostics.tick)*.05,wall_s:(finish.at-start.at)/1000};
   assert(finish.diagnostics.tick>start.diagnostics.tick,'Replay did not advance');
   row.playback.presented_wall_s=(finish.raf.last-start.raf.last)/1000;
   if(tag!=='before')assert(Math.abs(row.playback.observed_sim_s-row.playback.presented_wall_s)<.12,'Replay discards elapsed time between presented frames');
   await page.locator('#speed').selectOption('8');const fastStart=await snapshot();await page.waitForTimeout(2000);const fastEnd=await snapshot();
   row.fast={start:fastStart,finish:fastEnd,observed_sim_s:(fastEnd.diagnostics.tick-fastStart.diagnostics.tick)*.05,wall_s:(fastEnd.at-fastStart.at)/1000};
   await timeline.focus();await timeline.press('End');await page.waitForTimeout(300);row.end=await snapshot();
   if(tag!=='before'){
    assert(row.end.match_state==='回放已结束'&&row.end.transport.includes('重播'),'End of recording is not clearly identified');
    assert(row.end.diagnostics.tick===Number(row.end.timeline),'End seek left the renderer feed at the previous frame');
    await page.waitForFunction(tick=>window.arenaDiagnostics?.().renderedTick===tick,Number(row.end.timeline));
    if(label==='worker-0-episode-00009')assert(row.end.backend.includes('Warp · 20 Hz 全帧'),'Warp recording backend is mislabeled');
    await page.locator('#pause').click();await page.waitForTimeout(300);row.restarted=await snapshot();
    assert(Number(row.restarted.timeline)<Number(row.end.timeline),'Replay button did not restart the recorded segment');
   }
   await timeline.press('Home');await timeline.press('ArrowRight');await page.waitForTimeout(300);row.return_start=await snapshot();
   assert(Number(row.return_start.timeline)===1,'Seek back to start failed');
   if(report.cases.length<=2)await page.screenshot({path:path.join(out,tag+'-replay-'+report.cases.length+'.png'),fullPage:true});
   const t=Date.now(),state=await page.request.get(url+'/api/state');row.api_state_ms=Date.now()-t;row.service_busy=(await state.json()).busy;
   assert(!row.service_busy,'Unexpected live physics match');
   console.log(JSON.stringify({label,loaded_ms:row.loaded_ms,assets_ready_ms:row.assets_ready_ms,playback:row.playback.observed_sim_s,fast:row.fast.observed_sim_s,heap:row.return_start.memory}));
  }
  assert(report.mutations.length===0,'Probe unexpectedly made an API mutation');
  report.status=report.errors.length?'errors':'passed';
 }catch(e){report.status='failed';report.errors.push(e.stack||String(e));}
 finally{clearTimeout(timer);await browser?.close();report.finished=new Date().toISOString();fs.writeFileSync(path.join(out,tag+'-replay-stability.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({status:report.status,errors:report.errors}));}
 if(report.status!=='passed')process.exitCode=1;
})();

