const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {chromium}=require('/home/lx/kenreri/todo-list/.repo-tools/workspace-qa/node_modules/playwright-core');
const root=process.cwd(),source=path.join(root,'data/research/sentry-v6-20261111-0333/web-evidence/frozen-live-replay.json');
const report={started_unix:Date.now()/1000,limit_seconds:60,new_physics_matches:0,api_stubbed:false,mutations:[],page_errors:[],checks:[]};
const deadline=Date.now()+60000;let browser;
const remaining=()=>Math.max(1,Math.min(20000,deadline-Date.now()-5000));
const assert=(value,message)=>{if(!value)throw Error(message);};
(async()=>{
 const watchdog=setTimeout(()=>{void browser?.close();},55000);
 try{
  report.replay={path:path.relative(root,source),bytes:fs.statSync(source).size,sha256:crypto.createHash('sha256').update(fs.readFileSync(source)).digest('hex')};
  browser=await chromium.launch({executablePath:'/usr/bin/google-chrome',headless:true,timeout:remaining(),args:['--no-sandbox','--disable-dev-shm-usage','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']});
  const page=await browser.newPage({viewport:{width:1280,height:900}});page.setDefaultTimeout(remaining());
  page.on('pageerror',e=>report.page_errors.push(String(e)));
  page.on('request',r=>{if(r.method()!=='GET')report.mutations.push({url:r.url(),method:r.method()});});
  await page.goto('http://127.0.0.1:8776',{waitUntil:'domcontentloaded',timeout:remaining()});
  await page.getByRole('button',{name:'RM 对战',exact:true}).click();
  let oldGeneration;
  for(let load=0;load<2;load++){
   await page.locator('#replay-file').setInputFiles(source,{timeout:remaining()});
   await page.waitForFunction(previous=>{const d=window.arenaDiagnostics?.();return d?.mode==='replay'&&d.replayGeneration!==previous;},oldGeneration,{timeout:remaining()});
   const timeline=page.locator('#timeline');await timeline.focus();await timeline.press('Home');await timeline.press('ArrowRight');
   await page.waitForFunction(()=>{const d=window.arenaDiagnostics?.();return d?.tick===1&&d.replayPosition===1&&!d.replayPlaying&&d.renderedTick===1&&d.renderedGeneration===d.feedGeneration&&!document.querySelector('.scene-loading,.scene-recovery');},undefined,{timeout:remaining()});
   const current=await page.evaluate(()=>window.arenaDiagnostics());
   if(load)assert(current.renderedGeneration!==report.checks[0].renderedGeneration,'Second replay reused the old drawn generation');
   report.checks.push({load,tick:current.tick,position:current.replayPosition,playing:current.replayPlaying,renderedTick:current.renderedTick,renderedGeneration:current.renderedGeneration,feedGeneration:current.feedGeneration,replayGeneration:current.replayGeneration});
   oldGeneration=current.replayGeneration;
  }
  assert(report.mutations.length===0&&report.page_errors.length===0,'Unexpected mutation or page exception');
  report.status='passed_same_tick_distinct_generation';
 }catch(error){report.status='partial';report.error=error.stack||String(error);}
 finally{clearTimeout(watchdog);await browser?.close();report.finished_unix=Date.now()/1000;report.elapsed_seconds=report.finished_unix-report.started_unix;report.within_60_seconds=report.elapsed_seconds<=60;fs.writeFileSync(path.join(__dirname,'review-followup-browser.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));}
 if(report.status!=='passed_same_tick_distinct_generation'||!report.within_60_seconds)process.exitCode=1;
})();
